<?php auth();$id=(int)($_GET['id']??0);$s=$pdo->prepare('SELECT * FROM orders WHERE id=? AND user_id=?');$s->execute([$id,user()['id']]);$o=$s->fetch();if(!$o){http_response_code(404);die('سفارش پیدا نشد');}$si=$pdo->prepare('SELECT * FROM order_items WHERE order_id=?');$si->execute([$id]);$items=$si->fetchAll();$title='سفارش #'.$id;require __DIR__.'/partials/header.php';?><h1>سفارش #<?=$id?></h1><div class="two-col"><div class="panel table-wrap"><table class="table"><tr><th>محصول</th><th>قیمت</th><th>تعداد</th><th>جمع</th></tr><?php foreach($items as $i): ?><tr><td><?=e($i['product_name'])?></td><td><?=money($i['price'])?></td><td><?=$i['qty']?></td><td><?=money($i['price']*$i['qty'])?></td></tr><?php endforeach; ?></table></div><div class="panel"><p>گیرنده: <b><?=e($o['receiver'])?></b></p><p>آدرس: <?=nl2br(e($o['address']))?></p><p>وضعیت: <span class="badge"><?=e($o['status'])?></span></p><hr><p>مبلغ نهایی: <b><?=money($o['total'])?></b></p></div></div><?php require __DIR__.'/partials/footer.php'; ?>
